+	row := func(a *[2][2]int64) *[2]ptcInt64 { return (*[2]ptcInt64)(unsafe.Pointer(&a[1])) }
+	view := func(a *[2][2]int64) *[2][2]ptcInt64 { return (*[2][2]ptcInt64)(unsafe.Pointer(a)) }
+
+	// The order of the conversions must not matter.
+	var a, b [2][2]int64
+	if v, r := view(&a), row(&a); r != &v[1] {
+		t.Errorf("row converted after the array != row of the converted array")
+	}
+	if r, v := row(&b), view(&b); r != &v[1] {
+		t.Errorf("row converted before the array != row of the converted array")
+	}
+	var c [2][2]int64
+	if v1, v2 := view(&c), view(&c); &v1[0] != &v2[0] || &v1[1] != &v2[1] {
+		t.Errorf("rows of two conversions of an array are not equal")
+	}
+	var f [2][2]int64
+	if (*[2]ptcInt64)(unsafe.Pointer(&f[0])) != &view(&f)[0] {
+		t.Errorf("first row converted by itself != first row of the converted array")
+	}
+
+	// Round trips.
+	var d [2][2]int64
+	v := view(&d)
+	if (*[2]int64)(unsafe.Pointer(&v[1])) != &d[1] || unsafe.Pointer(&v[1]) != unsafe.Pointer(&d[1]) {
+		t.Errorf("row of the converted array converted back != row of the array")
+	}
+	if (*[2]int64)(unsafe.Pointer(row(&d))) != &d[1] {
+		t.Errorf("row converted back != row of the array")
+	}
+
+	// Reflected addresses.
+	var e [2][2]int64
+	w, r := view(&e), row(&e)
+	q := reflect.ValueOf(w).Elem().Index(1).Addr().Interface().(*[2]ptcInt64)
+	if q != r || q != &w[1] {
+		t.Errorf("reflect address of a row != direct address of it")
+	}
+	if p := reflect.ValueOf(&e).Elem().Index(1).Addr().Interface().(*[2]int64); (*[2]int64)(unsafe.Pointer(&w[1])) != p {
+		t.Errorf("row of the converted array converted back != reflect address of the row")
+	}
+
+	// Elements, through the rows.
+	g := [2][2]int64{{1, 2}, {3, 4}}
+	gv, gr := view(&g), row(&g)
+	gr[0] = 7
+	(&gv[1])[1] = 8
