+		t.Errorf("after writing through rows: g = %v, g[1][0] has type %s", g, ptcTypeName(g[1][0]))
+	}
+
+	// Deeper arrays and arrays in structs.
+	var h [2][2][2]int64
+	hv := (*[2][2][2]ptcInt64)(unsafe.Pointer(&h))
+	if (*[2]ptcInt64)(unsafe.Pointer(&h[1][1])) != &hv[1][1] || (*[2][2]ptcInt64)(unsafe.Pointer(&h[1])) != &hv[1] {
+		t.Errorf("rows of a converted three-dimensional array are not equal")
+	}
+	type rawGrid struct{ m [2][2]int64 }
+	type namedGrid struct{ m [2][2]ptcInt64 }
+	var s rawGrid
+	if (*[2]ptcInt64)(unsafe.Pointer(&s.m[1])) != &(*namedGrid)(unsafe.Pointer(&s)).m[1] {
+		t.Errorf("rows of an array in a converted struct are not equal")
+	}
+}
+
+func TestPtrConvJsObject(t *testing.T) {
+	defer ptcNoPanic(t)
+	o := js.Global.Get("Object").New()
+	o.Set("n", 1)
+	p := ptcJsPtr(o)
+	if p == nil || ptcTypeName(p) != "ptrconv_658733.ptcJsPtr" {
+		t.Fatalf("ptcJsPtr(o) = %v (%s)", p, ptcTypeName(p))
+	}
+	if p != ptcJsPtr(o) || p != ptcJsPtr(unsafe.Pointer(o)) {
+		t.Errorf("conversions of the same *js.Object are not equal")
+	}
+	if ptcTypeName(ptcJsPtr(unsafe.Pointer(o))) != "ptrconv_658733.ptcJsPtr" {
+		t.Errorf("ptcJsPtr(unsafe.Pointer(o)) has type %s", ptcTypeName(ptcJsPtr(unsafe.Pointer(o))))
+	}
+	if unsafe.Pointer(p) != unsafe.Pointer(o) {
+		t.Errorf("unsafe.Pointer(ptcJsPtr(o)) != unsafe.Pointer(o)")
+	}
+	var q ptcJsPtr = o
+	var back *js.Object = q
+	if q != p || back != o || (*js.Object)(p) != o {
+		t.Errorf("*js.Object converted back != o")
+	}
+	if n := (*js.Object)(p).Get("n").Int(); n != 1 {
+		t.Errorf("(*js.Object)(ptcJsPtr(o)).Get(\"n\") = %d", n)
+	}
+}
+
+// A broken conversion of the zero unsafe.Pointer to a struct pointer can abort
+// the whole test binary, so keep this test last.
+func TestPtrConvUnsafePointerNilStruct(t *testing.T) {
+	var up unsafe.Pointer
+	if (*ptcStruct)(up) != nil {
+		t.Errorf("(*ptcStruct)(nil unsafe.Pointer) != nil")
+	}
+	if (*ptcStruct2)(unsafe.Pointer((*ptcStruct)(nil))) != nil {
+		t.Errorf("nil struct pointer round trip through unsafe.Pointer is not nil")
+	}
+}
