+// Package unsafeptr_658733 tests conversions via a type defined from
+// unsafe.Pointer. It is a package of its own, as a compiler that can't
+// translate them fails to compile the whole package.
+package unsafeptr_658733
+
+import (
+	"fmt"
+	"testing"
+	"unsafe"
+)
+
+type (
+	upUnsafe  unsafe.Pointer
+	upInt     int
+	upInt64   int64
+	upStruct  struct{ n int64 }
+	upStruct2 struct{ n upInt64 }
+)
+
+func upTypeName(v any) string { return fmt.Sprintf("%T", v) }
+
+func TestPtrConvNamedUnsafePointer(t *testing.T) {
+	defer func() {
+		if r := recover(); r != nil {
+			t.Errorf("panic: %v", r)
+		}
+	}()
+	n := 1
+	u := upUnsafe(&n)
+	if q := (*upInt)(u); q != (*upInt)(&n) || upTypeName(*q) != "unsafeptr_658733.upInt" {
+		t.Errorf("(*upInt)(upUnsafe(&n)) = %v (%s)", q, upTypeName(*q))
+	}
+	if (*int)(u) != &n || unsafe.Pointer(u) != unsafe.Pointer(&n) {
+		t.Errorf("(*int)(upUnsafe(&n)) != &n")
+	}
+	*(*upInt)(u) = 7
+	if n != 7 {
+		t.Errorf("write through (*upInt)(upUnsafe(&n)): n = %d, want 7", n)
+	}
+	a := [2]int64{1, 2}
+	if v := (*[2]upInt64)(upUnsafe(&a)); upTypeName(v[1]) != "unsafeptr_658733.upInt64" || v[1] != 2 || (*[2]int64)(unsafe.Pointer(v)) != &a {
+		t.Errorf("(*[2]upInt64)(upUnsafe(&a)) = %v (%s)", v, upTypeName(v[1]))
+	}
+	s := &upStruct{n: 3}
+	if q := (*upStruct2)(upUnsafe(s)); upTypeName(q.n) != "unsafeptr_658733.upInt64" || q.n != 3 || (*upStruct)(unsafe.Pointer(q)) != s {
+		t.Errorf("(*upStruct2)(upUnsafe(s)).n = %v (%s)", q.n, upTypeName(q.n))
+	}
+	var nu upUnsafe
+	if (*int)(nu) != nil || (*upStruct)(nu) != nil || (*[2]int64)(nu) != nil {
+		t.Errorf("conversion of the zero upUnsafe is not nil")
+	}
+}
